#include "game.h"
#include "rules.h"
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
static int passed=0,failed=0;
#define CHECK(c) do{if(!(c)){printf("FAIL %-25s line %d: %s\n",__func__,__LINE__,#c);failed++;return;}}while(0)
#define PASS() do{passed++;printf("PASS %s\n",__func__);}while(0)
static void at(Actor *a,int x,int y,Direction d){*a=(Actor){.x=(float)x,.y=(float)y,.cx=x,.cy=y,.tx=x,.ty=y,.dir=d};}
static Game arena(bool extras){Game g;game_init(&g,1234,extras);for(int y=1;y<MAP_H-1;y++)for(int x=1;x<MAP_W-1;x++)g.map[y][x]=TILE_FLOOR;for(int i=0;i<MAX_MONSTERS;i++)g.monsters[i].alive=false;g.grace=0;return g;}
static void ticks(Game *g,int n,Direction d){for(int i=0;i<n;i++)game_tick(g,(Input){d,false});}
static int count_bombs(const Game *g){int n=0;for(int i=0;i<MAX_BOMBS;i++)n+=g->bombs[i].active;return n;}
static void test_skeleton(void){Game g;game_init(&g,42,false);CHECK(g.level==1&&g.lives==3&&g.score==0);CHECK(g.map[11][13]==TILE_EXIT);CHECK(g.monsters[0].kind==MONSTER_WHITE&&g.monsters[1].kind==MONSTER_YELLOW&&g.monsters[2].kind==MONSTER_GREEN);for(int x=0;x<MAP_W;x++)CHECK(g.map[0][x]==TILE_WALL);PASS();}
static void test_wall_collision(void){Game g=arena(false);CHECK(!game_can_enter(&g,-1,1));CHECK(!game_can_enter(&g,0,1));g.map[1][3]=TILE_WALL;ticks(&g,240,DIR_RIGHT);CHECK(fabsf(g.player.x-2)<.001f);CHECK(g.player.cy==1&&!g.player.moving);PASS();}
static void test_turn_only_at_center(void){Game g=arena(false);ticks(&g,10,DIR_RIGHT);CHECK(g.player.moving&&g.player.y==1);ticks(&g,10,DIR_DOWN);CHECK(g.player.y==1);ticks(&g,30,DIR_DOWN);CHECK(g.player.x==2&&g.player.y>1);PASS();}
static void test_three_monster_types(void){Game g;game_init(&g,17,false);float wx=g.monsters[0].body.x,yy=g.monsters[1].body.y;game_move_monsters(&g);CHECK(g.monsters[0].body.y>1);for(int i=0;i<3000;i++)game_move_monsters(&g);CHECK(g.monsters[0].body.x==wx);CHECK(g.monsters[1].body.y==yy);for(int m=0;m<3;m++){int x=(int)roundf(g.monsters[m].body.x),y=(int)roundf(g.monsters[m].body.y);CHECK(g.map[y][x]!=TILE_WALL&&g.map[y][x]!=TILE_BRICK);}PASS();}
static void test_green_starts_moving(void){Game g;game_init(&g,7,false);Monster *m=&g.monsters[2];for(int i=0;i<240;i++)game_move_monsters(&g);CHECK(m->body.x!=12||m->body.moving);PASS();}
static void test_green_wall_reverse(void){Game g=arena(false);Monster *m=&g.monsters[2];m->alive=true;m->kind=MONSTER_GREEN;at(&m->body,5,5,DIR_RIGHT);g.map[5][6]=g.map[4][5]=g.map[6][5]=TILE_WALL;game_move_monsters(&g);CHECK(m->body.dir==DIR_LEFT&&m->body.x<5);PASS();}
static void test_bomb_3_seconds(void){Game g=arena(false);at(&g.player,5,5,DIR_DOWN);CHECK(game_place_bomb(&g));for(int i=0;i<359;i++)game_update_bombs(&g);CHECK(count_bombs(&g)==1);game_update_bombs(&g);CHECK(count_bombs(&g)==0);CHECK(g.flame[5][5]>0);PASS();}
static void test_cooldown_5_seconds(void){Game g=arena(false);CHECK(game_place_bomb(&g));at(&g.player,10,10,DIR_DOWN);ticks(&g,599,DIR_NONE);CHECK(!game_place_bomb(&g));ticks(&g,1,DIR_NONE);CHECK(game_place_bomb(&g));CHECK(count_bombs(&g)==1);PASS();}
static void test_blast_brick_wall_range(void){Game g=arena(false);at(&g.player,5,5,DIR_DOWN);g.map[5][6]=TILE_BRICK;g.map[3][5]=TILE_WALL;CHECK(game_place_bomb(&g));g.bombs[0].fuse=0;game_update_bombs(&g);CHECK(g.map[5][6]==TILE_FLOOR&&g.score==0);CHECK(g.flame[5][6]>0&&g.flame[5][7]==0);CHECK(g.flame[4][5]>0&&g.flame[3][5]==0);CHECK(g.flame[7][5]>0&&g.flame[8][5]==0);CHECK(g.flame[5][3]>0);PASS();}
static void test_monster_score_once(void){Game g=arena(false);at(&g.player,10,10,DIR_DOWN);Monster *m=&g.monsters[0];m->alive=true;at(&m->body,5,5,DIR_DOWN);g.flame[5][5]=FLAME_TIME;game_check_collisions(&g);CHECK(!m->alive&&g.score==10);game_check_collisions(&g);CHECK(g.score==10);PASS();}
static void test_monster_damage_and_stun(void){Game g=arena(false);game_hit_player(&g,false);CHECK(g.lives==2&&g.score==-10&&g.stun==5);game_hit_player(&g,false);CHECK(g.lives==2&&g.score==-10);ticks(&g,599,DIR_NONE);CHECK(g.stun>0);ticks(&g,2,DIR_NONE);CHECK(g.stun==0&&g.player.x==1&&g.player.y==1);CHECK(g.grace>0);PASS();}
static void test_bomb_damage_and_gameover(void){Game g=arena(false);game_hit_player(&g,true);CHECK(g.lives==2&&g.score==-20);g.stun=0;game_hit_player(&g,true);g.stun=0;game_hit_player(&g,true);CHECK(g.lives==0&&g.phase==GAME_OVER&&g.score==-60);float t=g.time_left;ticks(&g,10,DIR_RIGHT);CHECK(g.time_left==t);PASS();}
static void test_simultaneous_collision_priority(void){Game g=arena(false);at(&g.player,5,5,DIR_DOWN);g.monsters[0].alive=true;at(&g.monsters[0].body,5.0f,5.0f,DIR_DOWN);g.flame[5][5]=FLAME_TIME;game_check_collisions(&g);CHECK(g.score==-10&&g.lives==2); /* kill +10, bomb hit -20, monster contact not charged */PASS();}
static void test_level_scaling_and_fixed_map(void){Game g;game_init(&g,12,false);g.map[5][9]=TILE_FLOOR;g.score=30;at(&g.player,13,11,DIR_DOWN);game_check_exit(&g);CHECK(g.level==2&&g.phase==LEVEL_FLASH&&g.score==30);CHECK(g.map[5][9]==TILE_BRICK);CHECK(fabsf(game_player_speed(&g)-3.9f)<.001f);CHECK(fabsf(game_monster_speed(&g)-1.92f)<.001f);CHECK(game_blast_range(&g)==3);g.phase=PLAYING;at(&g.player,13,11,DIR_DOWN);game_check_exit(&g);CHECK(g.level==3&&game_blast_range(&g)==4);CHECK(fabsf(game_player_speed(&g)-4.8f)<.001f);CHECK(fabsf(game_monster_speed(&g)-2.4f)<.001f);g.phase=PLAYING;at(&g.player,13,11,DIR_DOWN);game_check_exit(&g);CHECK(g.phase==ALL_CLEAR);PASS();}
static void test_level_flash_cycle(void){Game g;game_init(&g,12,false);at(&g.player,13,11,DIR_DOWN);game_check_exit(&g);CHECK(g.phase==LEVEL_FLASH);int whites=0;bool was=false;for(int i=0;i<107;i++){bool now=bm_level_flash(g.flash,0).white;whites+=now&&!was;was=now;game_tick(&g,(Input){DIR_NONE,false});CHECK(g.phase==LEVEL_FLASH);}CHECK(whites==3);game_tick(&g,(Input){DIR_NONE,false});CHECK(g.phase==PLAYING&&g.flash==0);PASS();}
static void test_flame_edge_hit(void){Game g=arena(false);Monster *m=&g.monsters[0];m->alive=true;at(&m->body,5,5,DIR_RIGHT);m->body.x=5.3f;at(&g.player,10,9,DIR_DOWN);g.player.x=10.3f;g.flame[5][6]=g.flame[9][11]=FLAME_TIME;game_check_collisions(&g);CHECK(!m->alive&&g.score==-10&&g.lives==2);PASS();}

static void test_timeout(void){Game g=arena(false);g.time_left=.001f;game_tick(&g,(Input){DIR_NONE,false});CHECK(g.phase==GAME_OVER&&g.time_left==0);PASS();}
static void test_long_simulation_bounds(void){Game g;game_init(&g,55,true);uint32_t r=123;for(int i=0;i<100000;i++){r=r*1664525u+1013904223u;if(g.phase==GAME_OVER||g.phase==ALL_CLEAR)game_init(&g,55,true);game_tick(&g,(Input){(Direction)((r>>16)%5),r%57==0});CHECK(isfinite(g.player.x)&&isfinite(g.player.y));CHECK(g.player.x>=1&&g.player.x<=MAP_W-2&&g.player.y>=1&&g.player.y<=MAP_H-2);CHECK(g.lives>=0&&g.lives<=3);}PASS();}
int main(void){test_skeleton();test_wall_collision();test_turn_only_at_center();test_three_monster_types();test_green_wall_reverse();test_green_starts_moving();test_bomb_3_seconds();test_cooldown_5_seconds();test_blast_brick_wall_range();test_monster_score_once();test_monster_damage_and_stun();test_bomb_damage_and_gameover();test_simultaneous_collision_priority();test_level_scaling_and_fixed_map();test_level_flash_cycle();test_flame_edge_hit();test_timeout();test_long_simulation_bounds();printf("\n%d passed, %d failed\n",passed,failed);return failed?1:0;}
